from pathlib import Path
import json,csv,re,collections
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports'
options=[]
def a(family,title,drafts,question,baseline,difference,support,counter,rival,tradeoff,economic,failure,dependency='Needs current local evidence and reliable source terms',status='Conditional direction; local unmet need and effect unmeasured'):
 options.append(dict(solution_id=f'SOL-{len(options)+1:02}',family=family,title=title,consolidated_draft_ids=drafts,customer_question=question,existing_capability_baseline=baseline,specific_possible_difference=difference,support_evidence_ids=support,counter_or_boundary_evidence_ids=counter,strongest_rival=rival,stakeholder_tradeoff=tradeoff,conditional_commercial_mechanism=economic,cost_status='Unknown; no implementation budget, fee share or ROI assumed',failure_condition=failure,critical_dependency=dependency,evidence_status=status,selection_status='User chooses; no rank or winner',implementation='No implementation or roadmap',benefit_status='Hypothesis, not measured effect'))
A='1. Vehicle and finance choices'
a(A,'A use-based vehicle decision brief',['OPT-C15','MO11','OPT-C25'],'Which specific vehicle fits my budget, journeys and charging situation?','Auto2000 already has HEV/ICE comparison and working finance simulation; Toyota has variant-specific service-cost guidance with a March 2024 basis.','Assess the unresolved use/charging/lifecycle trade-off using scoped current assumptions, rather than creating another generic calculator.',['M003','M004','M024','UX02'],['UX03','UX04','JX03','FC32'],'Price, stock or an unsuitable Toyota offer may dominate even excellent understanding.','Buyer relevance versus input effort and false precision; publisher consistency versus local terms.','Only additional suitable deliveries or realizable adviser effort savings.','Existing materials already resolve the decision, inputs are unreliable, or no suitable offer exists.')
a(A,'Practical home-charging readiness',['MO03'],'Can I actually charge where I live, not just prefer to?','PLN already provides home-charging and trip/charging tools; a dealer should not recreate utility authority.','Distinguish residential power, parking/building permission and model compatibility from a generic charger map.',['M004','M019','M035'],['M018','M005'],'A shared/public charging arrangement already fits, or building permission/vehicle price is binding.','Convenient advice versus qualified installer/building control.','Potential incremental viable BEV deliveries; partner fee and avoided cost unverified.','No consequential readiness uncertainty or permissible useful dealer role.','Utility/building/installer terms; coordinates alone cannot establish access')
a(A,'Finance status and total obligations',['OPT-C12','OPT-C13','MO08'],'What is only a simulation, and what has a lender actually committed?','The observed simulator works without mandatory contact/income, exposes insurance timing and returns repeatable outputs. SEVA already supplies approval-related routes.','Clarify current assumptions, required household inputs, validity and decision authority at the handoff to a real offer.',['M047','COMP-009','COMP-010'],['UX03','UX04'],'True affordability or underwriting, rather than information, prevents purchase.','Lender accuracy and necessary verification versus buyer effort/privacy.','Additional eligible financed deliveries or less repeated handling; no approval uplift assumed.','Customers understand status already or the offer remains unaffordable.','Actual lender terms, expiry and permissions; no final-approval guarantee')
a(A,'Purchase versus subscription on full obligations',['MO07'],'Would ownership or a mobility contract suit my use and cash flow?','KINTO already exists with included items, ownership and use conditions; it is not a new subscription category.','Compare actual eligible offers, end-of-term position, use limits and remaining charges.',['M044','M045'],['M003','M045'],'The customer prefers ownership or neither option is suitable/affordable.','Predictability versus restrictions, longer-term cost and control.','Only a verified attributable dealer/partner contribution; no group-wide revenue allocation.','No comparable eligible contract or consequential choice uncertainty.','Partner availability, personal-use eligibility and actual offers','Exploratory: current Auto2000 unmet demand not established')
B='2. Service work, access and parts'
a(B,'Understandable service work and bill changes',['MO01'],'What work is needed, what changed, and what am I paying for?','Service quotations, records and documentation may already exist; this run did not inspect private repair orders.','Assess whether scope, provisional estimates, authorized changes and final work form a comprehensible account.',['M008','M009','M040'],['M007','JX04'],'Current service customers already receive sufficient clarity; changes are legitimate work.','Service-adviser explanation and trust versus detail overload and inspection uncertainty.','Captured suitable jobs or reduced disputes/rework, after actual cost.','The issue is rare, obsolete, already explained or unrelated to communication.','Reliable current job, authorization and invoice records')
a(B,'An appointment commitment customers can interpret',['OPT-C03'],'Is this a request, an accepted time, or a completed service commitment?','Auto2000 already shows test-drive windows and subsequent contact; booking and guest routes exist.','Assess clarity of requested/reviewed/confirmed states and the customer consequence of any remaining ambiguity.',['COMP-038','UX05'],['JX05','UX08','M009'],'The current process works well and booking is not the important service decision.','Simple progress versus honest capacity/verification limits.','Only additional completed eligible work or avoided handling; requested bookings are not GP.','No consequential ambiguity or other constraints determine fulfillment.','Actual branch acceptance and capacity; no inference from disabled dates')
a(B,'Visit preparation and conditional timing',['OPT-C04','OPT-C11'],'What must happen before my visit, appraisal or advertised completion time?','Current forms already request task-specific vehicle/owner information; partners publish inspection and document prerequisites.','Assess whether preparation and the start point of a conditional time promise are clear before the customer commits effort.',['COMP-014','COMP-020','COMP-012'],['UX06','UX07'],'Existing advisers already prepare customers; repeated information is necessary verification.','Fewer wasted visits versus too much early information or data collection.','More completed eligible tasks per visit or realizable handling savings.','Preparation failures are uncommon or extra explanation changes no outcome.')
a(B,'A service route matched to the vehicle and job',['OPT-C17','OPT-C20','MO04'],'Can this branch or home-service route perform the work my vehicle actually needs?','Working broad branch filters, named B&P lookup, THS, guest booking and model-specific schedules already exist. A reported outlet total is not capacity.','Investigate granular model/job qualification and useful capability information beyond existing broad filters.',['FC12','M011','M012','UX06'],['JX05','FC33','UX08','UX09','M009'],'Vehicle-first questions already solve fit; no meaningful wrong routing exists.','Owner convenience versus technician skill, safe diagnosis and scarce capacity.','Additional suitable jobs net of travel and displaced work.','Current routing is adequate or capability data cannot be trusted.','Verified job/model/branch capability and available capacity','Not an established missing capability; local outcome gap untested')
a(B,'Compatible parts with clear coverage consequences',['OPT-C14'],'Is this part suitable, available and consistent with my applicable protection?','Official-parts conditions and dealer channels are a baseline; this run did not complete a compatible-part purchase.','Investigate a specific fit/availability/coverage decision rather than adding an undifferentiated parts catalogue.',['COMP-025','COMP-034'],['M013'],'Stock or price dominates; existing parts advisers already solve fit.','Owner choice versus fitment accuracy, returns and overbroad warranty claims.','Suitable parts contribution net of returns/rework; no unit margin assumed.','No consequential fit uncertainty or viable supply exists.','Verified vehicle/part compatibility, stock, actual warranty wording','Exploratory: local parts-task evidence incomplete')
C='3. Ownership records and protection'
a(C,'A vehicle-specific protection decision',['OPT-C05','OPT-C16','OPT-C24','MO02'],'Which service or protection benefit applies now, and what changes next?','T-Care, Lite, XTRA, paid protection routes, reminders and after-free-service alternatives already exist.','Assess the clarity of cohort eligibility, included versus paid work, continuation conditions and offer validity.',['M016','M017','COMP-004','COMP-044'],['JX03','FC20','FC05'],'Customers understand entitlements and choose providers rationally for quality, price or location.','Useful simplicity versus model exceptions and entitlement disputes.','Captured eligible jobs or agreed incremental product contribution; programme funding and margin unknown.','No material misunderstanding or reachable eligible need.')
a(C,'Protection after an ownership or use change',['OPT-C06','OPT-C07'],'What changes if the vehicle is sold, shared or used commercially?','Coverage terms already distinguish owner, transfer, use and campaign conditions; restrictions differ by programme.','Make the actual contract transition intelligible for a specific used buyer or fleet/private-use decision.',['COMP-034','COMP-036'],['INS-018'],'Current advice is adequate; no consequential transition problem exists.','Buyer/fleet clarity versus contract-specific complexity and privacy.','Only retained suitable sales/jobs; no transferable benefit assumed.','The relevant restriction does not apply or owners already understand it.','Current exact contracts; historic campaigns cannot define all current cover','Exploratory: household/fleet unmet need not demonstrated')
a(C,'A battery result explained in buyer terms',['OPT-C08','MO10'],'What does this result establish, and what does it leave uncertain?','Toyota already performs eligible checks and offers digital certificate retrieval.','Assess comprehension of date, scope, result and separate warranty responsibility, rather than claiming the first certificate.',['M015','COMP-006'],['JX02','FC31','M003'],'The battery is acceptable but price/product fit remains the binding issue.','Simple reassurance versus technical uncertainty and false precision.','Only additional appropriate transactions or less handling; no certificate-to-sale effect measured.','No reliable result or consequential interpretation gap exists.','Valid diagnostics and exact model/coverage scope')
a(C,'A coherent ownership record across jobs',['MO05'],'Can relevant service and protection context remain useful when my task changes?','mToyota advertises history/progress; Astra describes Single ID and service systems. Logged-out access cannot verify private record completeness.','Investigate specific missing/inconsistent context across maintenance, protection and replacement, with permission.',['COMP-001','M010','FC07'],['JX04','FC08','FC35'],'Customers prefer separate relationships or current records are already sufficient.','Owner continuity versus data quality, access roles and purposeful sharing.','Captured suitable work or realized rehandling savings; no automatic CLV uplift.','No meaningful continuity gap or usable permitted records.','Authorized accurate records; no public API or complete rollout assumed')
D='4. Replacement value'
a(D,'Condition evidence accepted in an appraisal',['OPT-C09'],'Would valid battery/history evidence change an actual appraiser decision?','Digital certificates, used-car inspection and BEV trade-in model selection already exist.','Investigate consented evidence acceptance and uncertainty in executable appraisal, not the first certificate or first BEV appraisal.',['COMP-005','M033','M034'],['JX02','JX07','M046','FC34'],'Physical condition and market demand determine the bid; prior records add little.','Seller convenience versus independent valuation and liability.','Additional retained trade-ins/deliveries or appraisal effort savings; no price premium assumed.','Appraisers cannot use the evidence or it adds no decision value.','Appraiser acceptance, record scope and data-sharing rights')
a(D,'Trade-in value with explicit uncertainty',['OPT-C10','MO06'],'Why can an online estimate differ from an inspected offer?','Auto2000 already describes inspection and a later offer; OLXmobbi distinguishes indicative and actual values.','Assess whether value status and remaining obligations are understood at the current decision point.',['M046','COMP-013','M003'],['UX07','JX07'],'Customers understand a fair process and simply dislike the market price.','Honest uncertainty versus desire for a decisive number.','Only retained viable replacements or lower rework; no guaranteed bid.','Market valuation, not information, is the binding problem.')
a(D,'A capped replacement incentive',['OPT-I04'],'Would a clearly limited extra trade-in credit change a viable next purchase?','Appraisal already exists; manufacturer resale promises show a different commercial precedent. No Auto2000 contract is verified.','Assess a capped benefit whose credit may remain below a target, separately from a full floor.',['INS-017','INS-019'],['INS-018','INS-021'],'The benefit subsidizes customers who would return anyway or concentrates adverse exercise.','Buyer value versus dealer subsidy, fairness and remarketing exposure.','Incremental delivery contribution minus actual capped benefit and other costs.','Incremental value does not cover subsidy or the cap is misunderstood.','High dependency: sponsor funding, redemption behavior and actual binding terms','Commercial concept; demand, liability terms and funding unverified')
a(D,'A contractual minimum trade-in value',['OPT-I05'],'Would a qualifying minimum value justify its full future obligation?','Selected manufacturers advertise qualified resale programmes; this is not proof of Auto2000 funding or equivalent eligibility.','Assess a genuine minimum-value promise as a distinct obligation from a capped credit.',['INS-017','INS-019'],['INS-018','INS-021','INS-028'],'Correlated price falls and exercise make the promise unaffordable or customers do not value it enough.','Buyer certainty versus retained loss, capital, conditions and partner disputes.','Incremental contribution must exceed loss, costs and any paid cover; no positive return assumed.','No credible capacity or acceptable economics to honor the entire customer obligation.','High dependency/risk: funding, exact contract, long-horizon price/exercise exposure','Unfunded concept in this evidence; no guarantee recommended')
E='5. Channel and relationship'
a(E,'One clear route for each ecosystem job',['OPT-C01'],'Which existing Toyota/Astra route should I use for this job?','Digiroom, mToyota, TASIA/TARRA and partner functions already exist.','Investigate role clarity and suitable next routes, not a new super-app simply because features overlap.',['COMP-001','COMP-002','FC17'],['FC14','FC16'],'Customers already know the routes; low monthly use reflects low need.','Central clarity versus distinct OEM/dealer/partner mandates.','Retained suitable opportunities or lower cost to serve; no MAU-to-GP shortcut.','No consequential route confusion appears.')
a(E,'Customer context carried into assisted help',['OPT-C02','MO09','OPT-I03'],'Can I get human help without restarting the task unnecessarily?','SAM, Single ID, advisers and insurer claim/SPK channels are existing systems, not missing infrastructure.','Assess a specific unresolved handoff; insurer repair authorization is a specialist facet of the same continuity job.',['M031','M041','FC04','FC07'],['FC08','INS-008','INS-013','UX05'],'Necessary requalification or human capacity, stock and credit explains the effort.','Customer continuity versus adviser workload, privacy and partner decision authority.','Additional fulfilled contribution or economically realizable handling savings.','Current context is adequate or the handoff adds no useful value.','Multi-party source/role access; no API, integration or fee assumed')
a(E,'Access that fits household or fleet roles',['OPT-C23'],'Who needs to see, approve or carry out this vehicle task?','Toyota OEM forms already allow another person to deliver the vehicle; comparator accounts have model/device rules.','Investigate the difference between multiple vehicles and delegated/concurrent users without sharing credentials.',['COMP-024','UX11'],['M045','JX04'],'Most relevant users need no shared role, or existing staff channels suffice.','Convenience versus account security, data purpose and payer accountability.','Only verified household/fleet opportunities or handling value; audience size unknown.','No consequential role separation or permissible access model.','OEM/security/contract roles; no account feature assumed','Exploratory: demand and permitted role arrangements unknown')
a(E,'Support timed to meaningful ownership jobs',['MO12'],'Can useful support arrive when there is a real job to complete?','Reminders, service programmes and transaction-based loyalty already exist.','Assess need-triggered relevance and successful quiet periods, rather than equating frequent opening with value.',['M011','M012','M016','M017'],['FC05','FC15'],'Frequent useful contact may independently help retention, or current reminders already work.','Owner attention versus marketing contact and missed-care risk.','Additional captured eligible work or savings; no assumed effect of extra notifications.','Current support is adequate or reduced contact would miss valuable needs.','Actual jobs due and cohort outcomes; public app inactivity cannot measure retention')
F='6. Emergency and connected use'
a(F,'Local emergency help with explicit scope',['OPT-C18'],'Which help is actually available for this vehicle, place and event?','Emergency contacts, OEM/insurer services and station tools exist with differing radii, hours and conditions.','Assess contact versus dispatch, charging, towing and customer charge boundaries for a real locality.',['COMP-030','COMP-031','COMP-033','COMP-040'],['M018','FC12'],'A simple reliable referral already solves the job.','Useful assurance versus physical capacity and potentially confusing exceptions.','Possible retention or handling savings; emergency service may have negative direct contribution.','No unresolved help task or reliable local information.','Verified locality/capability; coordinates and outlet totals do not prove field access')
a(F,'Mobility continuity during repair',['OPT-C19'],'How do I continue essential travel when the vehicle cannot be used?','Some comparator/partner programmes already offer conditional transport or optional replacement vehicles.','Investigate a specific unresolved repair-mobility need, not universal free replacement-car entitlement.',['COMP-030','M044'],['M045','INS-005'],'Existing insurer/household alternatives suffice and retained job value cannot cover support.','Owner relief versus subsidy, spare-vehicle capacity and partner liability.','Retained appropriate work only if contribution exceeds support/displacement cost.','No unmet demand, feasible supply or sustainable incremental value.','High dependency: eligibility, physical supply and partner economics','Exploratory: local entitlement and unmet demand unverified')
a(F,'Understandable vehicle-linked account setup',['OPT-C21'],'Why are connected functions unavailable and who can resolve it?','Connected OEM products and dealer-assisted linking exist; this study did not install or authenticate native apps.','Assess a specific setup/transfer explanation without assuming all linking fails or bypassing OEM security.',['COMP-023','COMP-024'],['FC17','UX12'],'The OEM process is adequate and the dealer adds no useful role.','Faster support versus vehicle/account security.','Possible lower support handling or retained relationship; no conversion effect measured.','No unresolved setup task or permitted dealer role.','OEM compatibility, ownership verification and account permissions')
a(F,'An informed connected-service renewal choice',['OPT-C22'],'What ends after the free period and what do I receive if I renew?','Connected services already exist; Hyundai comparator terms are not Toyota current contract terms.','Investigate an actual renewal decision separately from vehicle warranty.',['COMP-029'],['FC17'],'Users understand the distinction and choose renewal only when useful.','Ongoing utility versus subscription cost and expectations.','Only an agreed incremental partner/dealer contribution, if any; fee share unknown.','No relevant confusion or Auto2000 role.','Specific local contract, renewal price and provider authority','Exploratory: no Toyota-specific unmet renewal need established')
G='7. Insurance and risk transfer'
a(G,'A voluntary EV protection choice with real terms',['OPT-I01','OPT-I02','OPT-I07','OPT-I08'],'Which real policy, if any, fits my vehicle, risks and preferences?','EV-specific syariah cover, conventional/syariah motor lines, insurer claims apps and repair channels already exist.','Assess selected coverage, exclusions, deductible, workshop eligibility and voluntary priced preference; do not infer demand from Muslim population share.',['INS-001','INS-003','INS-004','INS-005','INS-006','INS-011'],['INS-007','INS-008','INS-009','INS-013'],'Customers understand existing cover or affordability matters more; new navigation duplicates insurers.','Choice clarity versus regulated marketing, data sharing, truthful coverage and insurer control.','Only verified incremental fee/vehicle/repair contribution; premium, insurer ujrah and surplus are not dealer GP.','No consequential gap, valid agreement or sustainable customer value.','High dependency: exact insurer product, distribution arrangement and permissible repair/data role','Existing product category; dealer value, fees and preference unverified')
a(G,'Investigate B2B residual-risk transfer',['OPT-I06'],'Could an actual insurer accept part of an actual residual obligation?','International custom B2B RVI exists. No local syariah contract, quote, acceptance or distribution arrangement was confirmed.','Investigate product availability and insurable exposure separately from the customer floor and dealer top-up.',['INS-020','INS-021'],['INS-022','INS-023','INS-024','INS-025','INS-027','INS-028'],'No suitable underwriter, trigger, contribution or retained-risk economics exists.','Promisor certainty versus exclusions, aggregate limits, timing, insurer risk and sharia/product assessment.','Eligible recoveries minus premium and retained exposure; no recoverability or cost saving assumed.','No verified feasible contract or residual liability remains unaffordable.','Highest dependency/risk: local availability, underwriting, regulatory/sharia assessment and contract','Research-only availability question; no compliance or product availability assertion')
# Build evidence registry so every internal reference has a file/ID/source locator.
registry={}
for path,key in [('workstreams/competition/evidence_matrix.json','record_id'),('workstreams/market/evidence.json','evidence_id'),('workstreams/friend_capabilities/claim_matrix.json','claim_id'),('workstreams/friend_insurance/claim_matrix.json','claim_id')]:
 for r in json.loads((ROOT/path).read_text()):registry[r[key]]={'path':path,'id_field':key,'id':r[key],'source_url':r.get('source_url'),'source_ids':r.get('source_ids'),'locator':r.get('document_locator') or r.get('locator') or r.get('printed_pages')}
for path in ['workstreams/journeys/journey_observations.json','workstreams/journeys/friendcontext_JX_observations.json']:
 for r in json.loads((ROOT/path).read_text())['observations']:registry[r['observation_id']]={'path':path,'id_field':'observation_id','id':r['observation_id'],'source_url':r.get('final_url') or r.get('start_url'),'locator':r.get('job') or r.get('candidate_tested')}
fc_sources={r['source_id']:r['url'] for r in json.loads((ROOT/'workstreams/friend_capabilities/sources.json').read_text())}
for k,r in registry.items():
 if not r['source_url'] and r.get('source_ids'):r['source_urls']=[fc_sources[s] for s in re.split(r'[;, ]+',r['source_ids']) if s in fc_sources]
review={r['option_id']:r for r in json.loads((ROOT/'reports/option_review.json').read_text())}
for o in options:
 ids=o['support_evidence_ids']+o['counter_or_boundary_evidence_ids'];assert all(i in registry for i in ids),[i for i in ids if i not in registry]
 o['evidence_interpretation']='Support documents a mechanism, stated programme or observed task; it does not establish an unmet Auto2000 need, prevalence or effect. Counter IDs include existing capability and scope boundaries, not only refutations.'
 o['independent_review']=[{'draft_id':d,'disposition':review[d]['disposition'],'reason':review[d]['reason'],'boundary':review[d]['evidence_boundary']} for d in o['consolidated_draft_ids'] if d in review]
 o['source_urls']=sorted(set(u for i in ids for u in ([registry[i]['source_url']] if registry[i].get('source_url') else registry[i].get('source_urls',[]))))
 o['record_costs_and_gp']='No realized Auto2000 cohort margin, causal uplift or implementation cost measured.'
 o['evidence_locators']={i:registry[i] for i in ids}
 if o['solution_id'] in ('SOL-16','SOL-17','SOL-27'):o['constructed_math_reference']={'path':'workstreams/friend_insurance/illustrative_risk_scenarios.csv','status':'Constructed illustrations only; not empirical evidence or an underwriting quote'}
raw_inputs=[('workstreams/competition/option_cards.json','option_id'),('workstreams/market/solution_directions.json','option_id'),('workstreams/friend_insurance/option_cards.json','option_id')]
raw_ids=[r[key] for path,key in raw_inputs for r in json.loads((ROOT/path).read_text())];mapped=set(d for o in options for d in o['consolidated_draft_ids']);assert set(raw_ids)==mapped,(set(raw_ids)-mapped,mapped-set(raw_ids))
assert len(options)==27
(OUT/'SOLUTION_MENU.json').write_text(json.dumps({'as_of':'2026-11-11','scope':'User-choice menu; no ranking, selected strategy, implementation or roadmap','raw_draft_count':len(raw_ids),'distinct_menu_concepts':len(options),'families':list(dict.fromkeys(o['family'] for o in options)),'count_note':'45 drafts consolidated into 27 analytical concepts, not 27 proven market opportunities','options':options},ensure_ascii=False,indent=2))
flat=[]
for o in options:flat.append({k:(' | '.join(v) if isinstance(v,list) and (not v or not isinstance(v[0],dict)) else json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else v) for k,v in o.items()})
fields=list(dict.fromkeys(k for r in flat for k in r))
with (OUT/'SOLUTION_MENU.csv').open('w',newline='',encoding='utf8') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(flat)
md=['# Solution menu for your choice','', 'The study gives you 27 distinct concepts grouped into seven families, consolidated from 45 draft cards. These are choices to examine, not 27 proven opportunities. Several are facets of broader customer jobs, and none is ranked or selected. Raw drafts and their independent reviews remain available.', '', 'Existing comparison, finance simulation, model-specific service-cost guidance, broad branch filters, booking, digital health-certificate retrieval and BEV trade-in selection are the starting point. The question is whether a specific unresolved decision or handoff adds useful value. The research does not support claiming the first calculator, first digital certificate or first BEV appraisal.', '', 'The short menu below shows the job and its proposed distinction. The same-numbered entries in SOLUTION_MENU.json/CSV provide the supporting and counterevidence IDs, stakeholder trade-off, conditional commercial mechanism, unknown costs, failure condition and exact source locators. All benefits remain hypotheses.']
for family in dict.fromkeys(o['family'] for o in options):
 md+=['',f'## {family}','','| Concept / customer question | Existing baseline and possible distinction | What could make it fail |','|---|---|---|']
 for o in options:
  if o['family']!=family:continue
  evidence=', '.join(o['support_evidence_ids'][:2]);counter=', '.join(o['counter_or_boundary_evidence_ids'][:2]);md.append('| **'+o['solution_id']+' · '+o['title']+'**<br>'+o['customer_question']+' | '+o['existing_capability_baseline']+' **Possible difference:** '+o['specific_possible_difference']+' | '+o['strongest_rival']+' **Boundary:** '+o['critical_dependency']+'. Support: '+evidence+'. Counter/baseline: '+counter+'. |')
md+=['','## Commercial consequences and dependencies','','The ordinary information/continuity concepts can create value only if they change a suitable completed sale, capture an eligible job, or save economically realizable work. A channel switch, notification, quote, requested appointment or extra app open is not automatically incremental gross profit. Missing private funnel, job, margin and cost data remains missing.','', 'Multi-party concepts need usable data, permission and a party able to fulfill the promise. Existing corporate systems or a disclosed outlet total do not prove available APIs, complete deployment, exact model/job capacity or a signed agreement. Geographic proximity does not establish a functioning compatible charger, admission or driving time.','', '**SOL-16, SOL-17 and SOL-27 are materially different obligations.** A capped trade-in credit can leave the customer below a target. A full floor makes the named promisor responsible for the qualifying minimum. A policy layer, if actually available, pays only within its terms and limits; it does not remove the remaining customer promise. The illustrative risk table is arithmetic, not an insurance offer.','', '**SOL-26 and SOL-27 require particular caution in interpretation.** A syariah EV motor product already exists, but its selected package, deductibles, authorized repair and distribution terms matter. No Auto2000 fee or local syariah RVI product was confirmed. General fatwas, a regulator framework, group affiliation and an international precedent do not establish product-specific approval, cooperation or profitability.','', '**The exploratory audience/contract concepts remain visibly conditional.** Subscription, household/fleet roles, replacement mobility and connected renewal lack a demonstrated current Auto2000 unmet demand in this study. They remain possible research directions, not a hidden recommendation.','', 'The user chooses which concepts deserve development. This menu contains no winner, rollout, budget allocation, product build or implementation plan.']
# Avoid HTML linebreak dependency in document converters: use a plain separator inside cells.
(OUT/'SOLUTION_MENU.md').write_text('\n'.join(md).replace('<br>',': '))
checks={'raw_draft_ids':raw_ids,'raw_draft_count':len(raw_ids),'mapped_draft_count':len(mapped),'menu_count':len(options),'families':dict(collections.Counter(o['family'] for o in options)),'evidence_refs_resolve':True,'every_raw_draft_mapped':True,'selection_made':False,'implementation_supplied':False,'json_shape':'object with options array'}
(OUT/'solution_menu_checks.json').write_text(json.dumps(checks,indent=2));print(json.dumps({k:v for k,v in checks.items() if k!='raw_draft_ids'},indent=2))
